; start.asm -- 3com-pktdrv cold entry + JIT composer (fully assembly, no C runtime).
;
; The driver is a single self-specializing TSR (docs/02). At load, COLD code detects the
; machine, then COMPOSES the hot path from position-independent fragments (build/frags_asm.inc,
; generated by tools/mkfrag.py from src/asm/frag/*.asm), baking decisions in as immediates.
; copy-down then packs the emitted image and DOS-keeps it; everything here is reclaimed.
;
; This file is the cold orchestration + composer. It must itself be 8088-clean (it runs on
; a 5150). The emitted hot path is the fragments, not this code.
;
; Build: nasm -f obj -> wlink (system dos). Entry point is ..start. No C, no C library.

cpu 8086
bits 16

%include "codegen.inc"
; Shared EL3 register constants (guarded; also pulled by the probe). build_plan needs them
; to compute the per-generation Window-1 base + TX-start command.
%include "el3_core.inc"
; Corkscrew (3C515) delta: bus-master DMA register block + descriptor layout (guarded; also
; pulled by isapnp). The resident TX DMA paths + the descriptor/ring reservations need these.
%include "el3_corkscrew.inc"

;==============================================================================
; DATA (initialized) -- fragment palette, plan template
;==============================================================================
segment _DATA public class=DATA use16

%include "frags_asm.inc"        ; f_*[], *_patches[], g_frags[], FRAG_TABLE_N

; The emit plan for a 3C509B (PIO floor): only the DATAPATH fragments are emitted -- the
; API dispatch and ISR are static resident code (resident.asm/isr.asm), which call the
; emitted TX/RX via g_off[]. Each step: db id ; dw imm0 (io_base, filled by build_plan).
g_plan:
    db FRAG_RX_PIO
g_plan_rx_imm:
    dw 0
    db FRAG_TX_PIO
g_plan_tx_imm:
    dw 0
G_PLAN_N        equ 2
PLAN_STEP_SIZE  equ 3

; diagnostic strings ($-terminated for INT 21h AH=09h)
msg_banner  db '3com-pktdrv floor (3C509 packet driver)', 13, 10, '$'
msg_cpu     db 'CPU class=', '$'
msg_nic     db 13, 10, '3C509 I/O=0x', '$'
msg_irq     db ' IRQ=0x', '$'
msg_mac     db ' MAC=', '$'
msg_no_nic  db 13, 10, 'No 3C509 found', 13, 10, '$'
msg_crlf    db 13, 10, '$'

; uninstall (`3cpd /u`)
sig_pktdrvr db 'PKT DRVR'                       ; resident signature (handler + 3); 8 bytes
msg_uninst  db 13, 10, '3com-pktdrv uninstalled', 13, 10, '$'
msg_notinst db 13, 10, '3com-pktdrv not installed', 13, 10, '$'

%ifdef CFG_FAKENIC
fake_mac    db 0x02, 0x60, 0x8C, 0x11, 0x22, 0x33   ; test MAC (3Com OUI 00:60:8C)
%endif

%ifdef CFG_DEBUG
msg_dbgon   db '[debug build]', 13, 10, '$'
msg_eeprod  db 13, 10, 'EEPROM prod=0x', '$'
msg_eeid    db ' mfg=0x', '$'
msg_emit    db 'emitted=0x', '$'
msg_txring  db 'TXRING=', '$'                   ; 8b.1: 0=single (286/386), 1=ring (486+)
msg_keep    db ' resident para=0x', '$'
msg_inst    db 13, 10, 'INSTALLED: INT 60h, IRQ vec=0x', '$'
%endif

;==============================================================================
; BSS -- COLD scratch only (above resident_end, reclaimed after install).
;==============================================================================
segment _BSS public class=BSS use16

g_cpu_class:    resb 1          ; CPU_8088 .. CPU_CPUID (set by detect_cpu)
g_nic_gen:      resb 1          ; detected generation (NIC_GEN_*): 0=3C509/B 1=3C515 2=Vortex 3=Boomerang 4=Cyclone
g_manual:       resb 1          ; 1 = manual /b= I/O base given -> skip the ID-port probe
g_force8:       resb 1          ; 1 = /8 given -> force the 8088-class (8-bit byte-loop) datapath
g_force286:     resb 1          ; 1 = /2 given -> force the 286-class datapath (16-bit PIO + single-transfer DMA)
g_force386:     resb 1          ; 1 = /3 given -> force the 386-class datapath (32-bit PIO + CONV_SINGLE DMA)
g_force486:     resb 1          ; 1 = /4 given -> force the 486-class datapath (32-bit PIO + CONV_RING DMA)
g_want_dma:     resb 1          ; 1 = /d given -> request bus-master TX DMA (resolved in build_plan)
g_want_large:   resb 1          ; 1 = /j given -> request FDDI-sized large frames (gated to 3C515)
tail_end:       resw 1          ; PSP command-tail end offset (cold arg scan)
g_emitted_len:  resw 1
g_keep_para:    resw 1

; composer scratch
g_pos:          resw 1          ; current write offset into resident_image
g_planptr:      resw 1
g_step:         resw 1
g_imm0:         resw 1
g_curid:        resb 1
                resb 1

%ifdef CFG_PNP
; ISA PnP isolation scratch (cold)
pnp_lfsr:       resb 1          ; running isolation checksum LFSR
pnp_saw:        resb 1          ; a card drove the bus (0x55AA seen)
pnp_next_csn:   resb 1          ; next CSN to hand out
pnp_found_csn:  resb 1          ; CSN of the matched 3Com card
pnp_id:         resb 9          ; isolated serial id: vendor[2] product[2] serial[4] csum[1]
                resb 1          ; pad to even
%endif

;==============================================================================
; STACK -- COLD: the composer/init working stack (reclaimed; the ISR uses isr_stack).
;==============================================================================
segment _STACK stack class=STACK use16
        resb 1024

;==============================================================================
; CODE
;
; _TEXT is in DGROUP (tiny model): CS = DS = ES = SS = DGROUP, one addressable segment, so
; the resident INT 60h handler / ISR (next milestone) can NEAR-call the emitted datapath in
; resident_image. The _BSS + _STACK tail is uninitialized -> minalloc, not stored in the file.
;==============================================================================
group DGROUP _TEXT _DATA _BSS _STACK
segment _TEXT public class=CODE use16

;==============================================================================
; RESIDENT region (kept) -- laid out FIRST so the TSR keeps only up to resident_end and
; reclaims everything after it (the cold composer / probe / init / diagnostics). Holds the
; INT 60h handler, the ISR, the resident state they touch, and the JIT-emitted datapath.
; resb here is stored in the file but stays resident (it must be low/kept).
;==============================================================================
%include "resident.asm"             ; pkt_handler (INT 60h API)
%include "isr.asm"                  ; nic_isr (RX + receiver upcall)

g_nic_io:       resw 1              ; detected I/O base (command reg at +0x0E, windowed cfg at +0x00..)
g_nic_irq:      resw 1              ; detected IRQ
g_dnlist_off:   resw 1              ; DownListPtr reg offset (per gen: 0x404 ISA 515, 0x24 PCI 90x)
g_uplist_off:   resw 1              ; UpListPtr reg offset   (per gen: 0x418 ISA 515, 0x38 PCI 90x)
g_w1_base:      resw 1              ; Window-1 data-register base = io_base + gen delta (FIFO/status/free)
g_tx_start:     resw 1              ; precomputed SET_TX_START command (early-start vs store-and-forward)
g_use_dma:      resb 1             ; 1 = bus-master DMA TX active (3C515, >=286): single-transfer on 286/386, ring on 486+
g_use_large:    resb 1             ; 1 = FDDI-sized large frames active (/j AND 3C515): allowLargePackets
g_rx_len_mask:  resw 1             ; RX length mask: 0x07FF std, 0x1FFF when large (13-bit 3C515 field)
g_tx_done:      resb 1             ; set by the ISR on TxComplete; awaited by dma_tx_single (286/386 path)
g_tx_in_flight: resb 1             ; 1 while dma_tx_single holds the DMA channel (re-entrance guard)
g_tx_ring:      resb 1             ; 1 = 486+ -> non-blocking TX ring (movsd copy); 0 = 286/386 -> blocking zero-copy single-transfer
g_csum_ok:      resb 1             ; 1 = NIC supports HW checksum insertion (Cyclone) AND DMA active
g_csum_mode:    resb 1             ; 1 = stack enabled checksum offload (CSUM_CTL) -> FSH bits per TX frame
; (the bus-master TX-DMA structures -- tx_descs / tx_slots -- are placed LAST, past resident_end_pio,
;  so the TSR drops them on the PIO floor; the 286/386 single-transfer path also drops tx_slots.)
g_mac:          resb 6             ; station address
; receiver handle table: per slot recv_off, recv_seg (0=free), type (0=match all)
htable:         resb MAX_HANDLES * HANDLE_SIZE

; ISR type-demux scratch
rx_len:         resw 1             ; current packet length
cur_handle:     resw 1             ; matched handle (slot offset)
appbuf_off:     resw 1             ; receiver's buffer (upcall-1 result)
appbuf_seg:     resw 1
hdr_buf:        resb 16            ; Ethernet header peek (14 bytes + pad)

; install/uninstall state (resident so the uninstall vendor fn can restore + free)
psp_seg:        resw 1             ; our PSP segment
old_int_off:    resw 1             ; previous INT 60h owner (off,seg for `lds`)
old_int_seg:    resw 1
old_irq_off:    resw 1             ; previous NIC IRQ owner
old_irq_seg:    resw 1
irq_vec:        resb 1             ; computed NIC IRQ vector number
pic_mask_orig:  resb 1             ; NIC IRQ line's PIC mask bit at install (restored at uninstall)
pic_casc_orig:  resb 1             ; master IRQ2-cascade mask bit at install (slave IRQ; restored at /u)
                resb 1             ; pad to word alignment

g_off:          resw FRAG__COUNT   ; emitted-fragment offsets (handler/ISR call via these)
g_isr_busy:     resb 1             ; ISR reentrancy guard
isr_work:       resb 1             ; per-interrupt RX work cap counter (MAX_RX_WORK down to 0)
isr_save_ss:    resw 1             ; interrupted task's SS:SP (private-stack switch)
isr_save_sp:    resw 1
isr_stack:      dw 0BEEFh          ; canary at the stack BOTTOM (CFG_DEBUG ISR check logs 'O' on clobber)
                resb 1534          ; the ISR's private stack -- must hold the register save, the
                                   ; far receiver upcall (arbitrary app code), the XMS RX path's
                                   ; INT 15h (BIOS) frame, AND a nested-IRQ entry layered on top.
                                   ; 512 was NOT enough: tcpip.lib's receiver upcall does TCP input
                                   ; + ACK-clocked transmit re-entering INT 60h, and on the slow-CPU
                                   ; deep branches (ring-full / PIO fallback inside the upcall-send)
                                   ; it overflowed -- first trashing isr_save_ss/sp below, so the
                                   ; ISR exit restored a bogus SS:SP harvested from the overflow's
                                   ; own frames (seg 02C6 + a return offset), relocating the
                                   ; interrupted app's stack INTO this segment; its next 4 KB
                                   ; pattern-fill then flattened the resident image from
                                   ; isr_stack_top downward (the 486-tier tcpsink wedge, task #57).
isr_stack_top:
RESIDENT_IMAGE_MAX equ 256         ; byte budget for the composed datapath (compose_resident enforces)
resident_image: resb RESIDENT_IMAGE_MAX   ; the composed datapath (tx + rx drain)

; --- statistics (resident; updated by the ISR / send_pkt, read by get_statistics) ---
stat_rx:        dw 0               ; packets received & delivered
stat_tx:        dw 0               ; packets transmitted
stat_rxerr:     dw 0               ; RX errors (card-flagged)
stat_rxdrop:    dw 0               ; RX dropped (no receiver / no buffer)
stat_irq:       dw 0               ; NIC interrupts serviced
stat_txunderrun: dw 0              ; TX underrun/jabber recoveries (early-start tuning)
stat_txwait:    dw 0               ; TX FIFO-room waits that timed out (fast-CPU stall)
stat_adapterfail: dw 0            ; adapter-failure RX-engine resets (ISR self-heal)
pkt_stats:      times 7 dd 0       ; Crynwr get_statistics struct (built on demand)

%ifdef CFG_DEBUG
; --- debug event-log ring (resident; appended by the ISR / handler, dumped by pktdbg) ---
DBG_LOG_SIZE    equ 512
dbg_sig:        db 'PKTDBG01'      ; bumped: block now carries TX-ring diag counters at sig+8
; --- TX-ring DMA diagnostic counters (task #54: discriminate ring-full vs busy-stuck vs TCP-wait).
;     Fixed layout at sig+8.. read by txdiag.com via AH=0x7F (returns DS:SI -> dbg_sig). All cheap
;     `inc word [mem]` (no dbg_logb call), so they barely perturb the 100Mbit TX-ring timing. ---
txd_max_count:   dw 0   ; sig+8   peak tx_ring_count seen (ring-depth high-water mark)
txd_pio_fallb:   dw 0   ; sig+10  ring-full -> PIO fallbacks (foreground couldn't enqueue)
txd_drained:     dw 0   ; sig+12  total descriptors retired by the drain loop
txd_kick:        dw 0   ; sig+14  tx_kick calls (StartDmaDown issued)
txd_cpl_seen:    dw 0   ; sig+16  TxComplete ISR entries that reached .tx_ring_adv
txd_busy_stuck:  dw 0   ; sig+18  enqueue hit ring-full in ISR ctx (completion couldn't drain it)
txd_full_spins:  dw 0   ; sig+20  eq_wait HLT spins (foreground blocked waiting for a free slot)
txd_spare:       dw 0   ; sig+22  reserved
dbg_log_head:   dw 0               ; ring write index (wraps at DBG_LOG_SIZE)
dbg_log:        times DBG_LOG_SIZE db 0
%endif

; --- end of the always-resident (PIO floor) region. When the bus-master DMA path is inactive
;     (g_use_dma == 0) the TSR keeps only up to here, reclaiming the DMA region below (~4.6 KB).
resident_end_pio:
global resident_end_pio

; bus-master TX-DMA structures -- kept ONLY when the DMA path is active (gated on g_use_dma), so
; they sit past resident_end_pio and the PIO floor drops them. RX is always PIO (no RX-DMA buffer/
; descriptor), so only the TX descriptors + ring slots live here. dword-aligned; descriptor layout
; matches the emulator EL3 Down desc (next/status/addr/length). tx_descs[0] doubles as the 286/386
; single-transfer down descriptor (the ring is 486+ only); the TX slots below the single boundary
; exist only for the 486+ ring, so the 286/386 path drops them too.
                alignb 4
tx_descs:       resb TX_RING_N * EL3_DESC_SIZE  ; TX ring descriptors (card DMA-reads them); [0] also serves the 286/386 single-transfer
                alignb 4

resident_end_single:               ; <== TSR keep boundary for the 286/386 single-transfer DMA path (descriptors only)
global resident_end_single

; XMS DMA receive ring state -- present whenever g_use_dma=1 (286+).
; 286/386: kept through resident_end_xms_single (drops tx_slots / ring vars).
; 486+:    kept through resident_end (includes tx_slots for the TX ring).
xms_dma_armed:  resb 1             ; 0 = PIO / not configured; 1 = XMS ring armed
xms_rx_policy:  resb 1             ; xms_mem_policy_t (VCPI=0, DPMI=1, XMS_COPY=2)
xms_slot_idx:   resb 1             ; current ping-pong slot index (0 or 1)
                resb 1             ; pad to word alignment
xms_cfg_off:    resw 1             ; far ptr to caller's xms_rx_cfg_t (offset)
xms_cfg_seg:    resw 1             ; far ptr to caller's xms_rx_cfg_t (segment)
xms_slot_sz:    resw 1             ; bytes per XMS slot
                resw 1             ; pad to dword alignment
                alignb 16
xms_rx_desc0:   resb EL3_DESC_SIZE ; RX up-descriptor slot 0 (16 bytes, 16-byte aligned)
xms_rx_desc1:   resb EL3_DESC_SIZE ; RX up-descriptor slot 1
xms_gdt:        resb 48            ; INT 15h AH=87h GDT (6 x 8-byte entries; access bytes pre-set)

; R1.c Stage 1 (docs/13): driver-resident N-slot RX-DMA ring. xms_rx_n>0 selects this path in
; xms_rx_deliver (else the legacy 2-descriptor path above). Present on the DMA tier only.
xms_rx_n:       resb 1             ; active N-slot ring depth (0 = N-slot ring not configured)
                resb 1             ; pad
xms_ring_tail:  resw 1             ; ISR consume cursor (next slot to claim), 0..xms_rx_n-1
                alignb 16
xms_rx_ring:    resb EL3_RX_RING_N * EL3_DESC_SIZE      ; N UPDs (16 B each), NEXT-chained circular
                alignb 16
xms_rx_slotbuf: resb EL3_RX_RING_N * EL3_RX_SLOT_STRIDE ; N paragraph-aligned landing buffers (Stage 1 only)

; R1.c Stage 2 (docs/13): completion/free-ring zero-copy RX. When the stack supplies app-owned
; slots + a completion ring + a free ring (cfg2.slots_lin/compl_ring_lin/free_ring_lin all set),
; xms_rx_mode=1: the UPD ADDRs point at the APP buffers (not xms_rx_slotbuf), and on RX the ISR
; POSTS {slot_id,len,status,seq} to the completion ring instead of the upcall copy. The stack
; processes the frame in place and returns the slot via the free ring; RX_REFILL (0x06) -- and the
; ISR opportunistically -- drains the free ring, clearing UPD STATUS + xms_rx_posted[] to re-arm.
xms_rx_mode:    resb 1             ; 0 = Stage 1 upcall (driver slotbuf); 1 = Stage 2 completion ring
                resb 1             ; pad
xms_compl_off:  resw 1             ; completion ring far ptr (offset) -> xms_ring_hdr_t + entries
xms_compl_seg:  resw 1             ; completion ring segment
xms_free_off:   resw 1             ; free ring far ptr (offset) -> xms_ring_hdr_t + entries
xms_free_seg:   resw 1             ; free ring segment
xms_compl_seq:  resw 1             ; monotonic sequence stamped into each completion entry
xms_rx_posted:  resb EL3_RX_RING_N ; per-slot: 1 = completion posted, awaiting app free (STATUS stays
                                   ; UP_COMPLETE so the engine can't refill). Cleared on free -> re-arm.
                alignb 2

; 8b.2a: caller-phys TX pool (registered via TX_CONFIGURE) + a dedicated TX down-descriptor.
; Blocking single-transfer (caller-phys variant of dma_tx_single), used on ALL DMA tiers
; (gated on g_use_dma, independent of g_tx_ring); the dedicated descriptor never touches the
; ring's tx_descs[]. Present whenever g_use_dma (kept on 286/386 and 486+).
                  alignb 4
xms_tx_armed:     resb 1           ; 1 = TX pool registered via TX_CONFIGURE
xms_tx_in_flight: resb 1           ; 1 = a TX_SUBMIT single-transfer is DMAing now. The TxComplete
                                   ; ISR checks this FIRST and sets g_tx_done (skipping tx_ring_adv),
                                   ; so completion works on every tier independent of g_tx_ring and
                                   ; never disturbs the 486+ ring's bookkeeping.
xms_tx_pool_phys: resd 1           ; caller TX pool base phys (< DMA_ISA_16M_LIMIT)
xms_tx_pool_len:  resd 1           ; caller TX pool length (bytes)
                  alignb 4
xms_tx_desc:      resb EL3_DESC_SIZE + 8 ; dedicated TX down-descriptor (NOT the ring's tx_descs[]).
                                   ; 24 bytes: 8-byte header (NEXT+FSH) + up to TWO 8-byte fragment
                                   ; pairs -- single-fragment TX_SUBMIT uses frag0 only; TX_SUBMIT_SG
                                   ; uses frag0 (header template) + frag1 (payload in place).

resident_end_xms_single:          ; <== TSR keep boundary: 286 DMA + XMS (drops TX ring slots)
global resident_end_xms_single

tx_slots:       resb TX_RING_N * TX_SLOT_SZ     ; 486+ ring frame slots (dma_tx_enqueue copies the frame in)
tx_ring_head:   resw 1             ; next slot to fill (producer: send_pkt)
tx_ring_tail:   resw 1             ; oldest in-flight slot (consumer: TxComplete ISR)
tx_ring_count:  resw 1             ; frames currently queued (0..TX_RING_N)
tx_dma_busy:    resb 1             ; 1 while a slot's DMA is in flight
                resb 1             ; pad to even

resident_end:                      ; <== TSR keep boundary for the 486+ ring DMA path
global resident_end

;==============================================================================
; COLD region (reclaimed after install) -- entry, detection, compose, install, diagnostics.
;==============================================================================
..start:
        mov     bp, es              ; ES = PSP at .EXE entry -- save for the TSR keep
        mov     ax, DGROUP
        mov     ds, ax
        mov     es, ax              ; composer uses ES:DI for the emit destination
        ; Clear the cold parse/detect flags. They live in _BSS, which DOS does NOT zero on
        ; .EXE load: a fresh boot happens to hand us zeroed memory, but a RELOAD (3cpd /u
        ; then 3cpd again) lands in dirty freed memory -- a stale g_force8 there forces the
        ; 8088 8-bit datapath (wrong on a 16-bit 3C515) and disables DMA. (ES = DGROUP here.)
        cld
        mov     di, g_cpu_class
        mov     cx, 9               ; g_cpu_class, g_nic_gen, g_manual, g_force8/286/386/486, g_want_dma, g_want_large
        xor     al, al
        rep     stosb
        mov     [psp_seg], bp

        ; --- command tail scan ---
        ;   /u        uninstall the resident driver and exit
        ;   /b=NNN    manual I/O base (hex) -> skip the ID-port probe, attach at NNN
        ;   /q=NN     manual IRQ (decimal)  -> used with /b=
        ; Manual config lets the driver bind to a card at a known base (PnP-only cards, odd
        ; setups, or an emulator) without the ID-port contention.
        mov     es, bp              ; ES = PSP for the tail scan
        mov     al, [es:0x80]       ; command-tail length
        xor     ah, ah
        add     ax, 0x81            ; AX = end offset
        mov     [tail_end], ax
        mov     si, 0x81
.scan_tail:
        cmp     si, [tail_end]
        jae     .args_done
        cmp     byte [es:si], '/'
        jne     .st_next
        mov     al, [es:si + 1]
        or      al, 0x20            ; tolower
        cmp     al, 'u'
        je      do_uninstall
        cmp     al, 'b'
        je      .opt_base
        cmp     al, 'q'
        je      .opt_irq
        cmp     al, '8'
        jne     .chk_286
        mov     byte [g_force8], 1  ; force 8-bit byte-loop datapath (test the 8088 fragment)
        jmp     .st_next
.chk_286:
        cmp     al, '2'
        jne     .chk_386
        mov     byte [g_force286], 1 ; force 286-class datapath (test 286 16-bit PIO + single-transfer DMA)
        jmp     .st_next
.chk_386:
        cmp     al, '3'
        jne     .chk_486
        mov     byte [g_force386], 1 ; force 386-class datapath (32-bit PIO + CONV_SINGLE DMA)
        jmp     .st_next
.chk_486:
        cmp     al, '4'
        jne     .chk_dma
        mov     byte [g_force486], 1 ; force 486-class datapath (32-bit PIO + CONV_RING DMA)
        jmp     .st_next
.chk_dma:
        cmp     al, 'd'
        jne     .chk_large
        mov     byte [g_want_dma], 1 ; /d -> request bus-master TX DMA (gated to 3C515 + >=286)
        jmp     .st_next
.chk_large:
        cmp     al, 'j'
        jne     .chk_gen
        mov     byte [g_want_large], 1 ; /j -> request FDDI-sized large frames (gated to 3C515)
        jmp     .st_next
.chk_gen:
        cmp     al, '5'
        jne     .st_next
        mov     byte [g_nic_gen], 1 ; /5 -> Corkscrew (3C515): EEPROM +0x2000, W1 base +0x10
.st_next:
        inc     si
        jmp     .scan_tail
.opt_base:
        add     si, 3               ; skip "/b="
        call    parse_hex16         ; ES:SI -> hex -> BX, SI advanced
        mov     [g_nic_io], bx
        mov     byte [g_manual], 1
        jmp     .scan_tail
.opt_irq:
        add     si, 3               ; skip "/q="
        call    parse_dec16         ; ES:SI -> decimal -> BX, SI advanced
        mov     [g_nic_irq], bx
        jmp     .scan_tail
.args_done:
        mov     ax, DGROUP
        mov     es, ax              ; restore ES = DGROUP for the composer

        mov     dx, msg_banner
        call    print_str
%ifdef CFG_DEBUG
        mov     dx, msg_dbgon
        call    print_str
%endif

        call    detect_cpu          ; -> g_cpu_class
        cmp     byte [g_force8], 0  ; /8 -> force the 8088-class datapath (test 8-bit PIO on a fast CPU)
        je      .chk_force286
        mov     byte [g_cpu_class], CPU_8088
        jmp     .cpu_ok
.chk_force286:
        cmp     byte [g_force286], 0 ; /2 -> force the 286-class datapath (16-bit PIO + single-transfer DMA)
        je      .chk_force386
        mov     byte [g_cpu_class], CPU_80286
        jmp     .cpu_ok
.chk_force386:
        cmp     byte [g_force386], 0 ; /3 -> force the 386-class datapath (32-bit PIO + CONV_SINGLE DMA)
        je      .chk_force486
        mov     byte [g_cpu_class], CPU_80386
        jmp     .cpu_ok
.chk_force486:
        cmp     byte [g_force486], 0 ; /4 -> force the 486-class datapath (32-bit PIO + CONV_RING DMA)
        je      .cpu_ok
        mov     byte [g_cpu_class], CPU_80486
.cpu_ok:
        mov     dx, msg_cpu
        call    print_str
        mov     al, [g_cpu_class]
        add     al, '0'
        call    print_char          ; CPU class digit (0=8088,1=286,2=386,3=486,4=CPUID)

        ; --- 5150 short-circuit -------------------------------------------------
        ; On an 8088/8086 the capability axis collapses to PIO: no protected mode, no
        ; bus-master, no VMM. The >=286-only cold work (bus-master DMA validation and its
        ; VDS/cache machinery) is deferred to the Corkscrew generation, so today both paths
        ; fall straight through to the floor PIO compose. The split is kept as the documented
        ; hook for that >=286 work.
        cmp     byte [g_cpu_class], CPU_8088
        jbe     .floor
        call    phase_validate_dma      ; (>=286) bus-master DMA validation -- deferred to Corkscrew
.floor:
        ; ISA NIC detection. The native 3Com ID-port sequence is the universal EtherLink III
        ; ISA mechanism and runs on ANY CPU -- it's just port I/O. ISA PnP is a SEPARATE
        ; software protocol over fixed ports (0x279/0xA79 + relocatable read) that ALSO works
        ; on any ISA bus: it is NOT CPU-dependent (no PnP BIOS or 286+ needed to run the
        ; isolation -- a software PnP manager does it). PnP only matters for a 3C509B left in
        ; PnP-only mode or already claimed by a PnP BIOS, so it is a FULL-PROFILE add
        ; (CFG_PNP), compiled out of the minimal floor for size -- gated by profile, not CPU.
%ifdef CFG_FAKENIC
        ; test build (no emulator has a 3C509): skip the probe, inject a fake NIC so the
        ; full el3_init -> compose -> install path runs and the resident driver is testable.
        mov     word [g_nic_io], 0x300
        mov     word [g_nic_irq], 0x000A
        mov     si, fake_mac
        mov     di, g_mac
        mov     cx, 6
        rep     movsb
        clc
%else
        ; manual config (/b= given): skip the ID-port probe, attach at the specified base.
        cmp     byte [g_manual], 1
        jne     .auto_detect
        cmp     word [g_nic_irq], 0
        jne     .have_irq
        mov     word [g_nic_irq], 0x000A    ; default IRQ 10 if /q= omitted
.have_irq:
        call    el3_load_mac_io             ; read MAC via Window-0 EEPROM at the given base
        clc
        jmp     .nic_found
.auto_detect:
%ifdef CFG_PCI
        ; PCI first on >=386: mechanism-#1 config access needs 32-bit port I/O,
        ; and a machine carrying an EtherLink III PCI card should bind it in
        ; preference to any ISA leftovers. Miss -> fall through to PnP/ID-port.
        cmp     byte [g_cpu_class], CPU_80386
        jb      .pci_skip
        call    detect_nic_pci      ; -> g_nic_io/irq/gen/mac, I/O + bus-master enabled
        jnc     .nic_found
.pci_skip:
%endif
%ifdef CFG_PNP
        ; >=286 (16-bit ISA): try ISA PnP first -- it finds a 3C515 AND a PnP-mode 3C509B --
        ; then fall back to the legacy ID-port. On an 8088 a 3C515 can't exist (16-bit card)
        ; so we go straight to the legacy probe and skip the PnP subsystem entirely.
        cmp     byte [g_cpu_class], CPU_8088
        jbe     .legacy_only
        call    detect_nic_pnp      ; direct ISA PnP isolation -> g_nic_io/irq/mac
        jnc     .nic_found
.legacy_only:
        call    detect_nic          ; legacy 3Com ID-port (Tomahawk)
%else
        call    detect_nic          ; floor: native 3Com ID-port (Tomahawk) only
%endif
%endif
        jc      .nic_none           ; no card found
.nic_found:
        mov     dx, msg_nic         ; "3C509 I/O=0x"
        call    print_str
        mov     ax, [g_nic_io]
        call    print_hex16
        mov     dx, msg_irq         ; " IRQ=0x"
        call    print_str
        mov     ax, [g_nic_irq]
        call    print_hex16
        call    print_mac           ; " MAC=xx:xx:.."
        mov     dx, msg_crlf
        call    print_str

        call    build_plan          ; per-gen Window-1 base + TX-start cmd + PIO immediates
%ifdef CFG_DEBUG
        ; 8b.1 tier verification: g_tx_ring resolved by build_plan (286/386=0 single, 486+=1 ring).
        mov     dx, msg_txring
        call    print_str
        mov     al, [g_tx_ring]
        add     al, '0'
        call    print_char          ; 0 = single-transfer, 1 = ring
        mov     dx, msg_crlf
        call    print_str
%endif
        call    el3_init            ; bring the activated card to operational state (uses g_tx_start)

        call    compose_resident    ; ax = emitted length, fills resident_image + g_off
        or      ax, ax
        jz      .fail
        mov     [g_emitted_len], ax
%ifdef CFG_DEBUG
        mov     dx, msg_emit
        call    print_str
        mov     ax, [g_emitted_len]
        call    print_hex16
%endif

        call    copy_down           ; ax = paragraphs to keep
        mov     [g_keep_para], ax

        call    install             ; hook INT 60h, free env, DOS TSR-keep (never returns)
        ; (NIC IRQ hook + ISR receiver upcall land with real 3c509 hardware)
.nic_none:
        mov     dx, msg_no_nic
        call    print_str
.fail:
        mov     ax, 0x4C01
        int     0x21

;------------------------------------------------------------------------------
; do_uninstall -- `3cpd /u`: find the resident driver via the INT 60h vector + the
; "PKT DRVR" signature, ask it to tear down (vendor fn 0x82 restores vectors + masks the
; IRQ and returns its PSP in BX), then free its memory block. Separate process from the
; resident instance, so freeing the resident block is safe.
;------------------------------------------------------------------------------
do_uninstall:
        mov     ax, DGROUP
        mov     ds, ax
        mov     ax, 0x3500 | PKTINT     ; get INT 60h vector -> ES:BX
        int     0x21
        ; verify "PKT DRVR" at ES:BX+3 before trusting the vector
        mov     di, bx
        add     di, 3
        mov     si, sig_pktdrvr
        mov     cx, 8
.sigcmp:
        mov     al, [si]
        cmp     al, [es:di]
        jne     .notinst
        inc     si
        inc     di
        loop    .sigcmp
        ; it's ours -- tear down, then free the resident block
        mov     ah, 0x82                ; PD_UNINSTALL -> BX = resident PSP
        int     PKTINT
        mov     es, bx
        mov     ah, 0x49                ; free the resident memory block
        int     0x21
        mov     dx, msg_uninst
        call    print_str
        mov     ax, 0x4C00
        int     0x21
.notinst:
        mov     dx, msg_notinst
        call    print_str
        mov     ax, 0x4C01
        int     0x21

;------------------------------------------------------------------------------
; detect_cpu -- full non-CPUID class ladder: 8088 / 286 / 386 / 486 / CPUID-capable.
; Sets g_cpu_class. The 8086/286 split is the 16-bit FLAGS bits 12-15 test (8088-safe);
; the 386/486/CPUID split uses the 32-bit EFLAGS AC and ID flags (only reached on 386+, so
; the floor never executes a 32-bit instruction). Finer family/feature detail needs the
; CPUID-parsing layer (lifted when the cache-coherency tier lands). ~122 bytes, cold.
;------------------------------------------------------------------------------
detect_cpu:
        pushf
        pop     ax
        mov     cx, ax              ; save original FLAGS
        and     ax, 0x0FFF          ; try to clear bits 12-15
        push    ax
        popf
        pushf
        pop     ax
        and     ax, 0xF000
        cmp     ax, 0xF000          ; stuck set -> 8086/8088
        je      .is8088
        or      cx, 0xF000          ; try to set bits 12-15
        push    cx
        popf
        pushf
        pop     ax
        and     ax, 0xF000
        jz      .is286              ; stuck clear (can't set in real mode) -> 286
        ; --- 386+ : 32-bit EFLAGS tests (unreachable on 8086/286) ---
        cpu 386
        pushfd
        pop     eax
        mov     ecx, eax
        xor     eax, 0x00040000     ; toggle AC (bit 18): 386 can't, 486+ can
        push    eax
        popfd
        pushfd
        pop     eax
        xor     eax, ecx
        test    eax, 0x00040000
        jz      .is386
        mov     eax, ecx
        xor     eax, 0x00200000     ; toggle ID (bit 21): no-CPUID can't, CPUID can
        push    eax
        popfd
        pushfd
        pop     eax
        xor     eax, ecx
        test    eax, 0x00200000
        jz      .is486
        mov     byte [g_cpu_class], CPU_CPUID
        ret
.is486:
        mov     byte [g_cpu_class], CPU_80486
        ret
.is386:
        mov     byte [g_cpu_class], CPU_80386
        ret
.is286:
        mov     byte [g_cpu_class], CPU_80286
        ret
.is8088:
        mov     byte [g_cpu_class], CPU_8088
        ret
        cpu 8086                    ; restore floor-safety check for the rest of the file

;------------------------------------------------------------------------------
; phase_validate_dma (>=286 cold phase) -- DEFERRED to the 3C515 (Corkscrew) generation.
; The 3C509 (Tomahawk) is pure PIO: no bus-master, so there is no DMA engine to test and no
; cache-coherency / VDS bounce-buffer concern. The test-before-trust DMA validation (the
; cache-kit NC-region / cache-flush lift) -- plus the V86/protected-mode detection it needs
; (V86 is 386+-only, so gated there, not here) -- lands when the bus-master ring datapath does.
;------------------------------------------------------------------------------
phase_validate_dma:
        ret

; detect_nic / id_read_eeprom / io_delay -- the real 3C509B ISA probe + activation.
%include "el3_probe.asm"

; el3_init -- operational bring-up of the activated card (MAC, media, RX/TX enable).
%include "el3_init.asm"

%ifdef CFG_PNP
; detect_nic_pnp -- direct ISA PnP isolation (3C515 / PnP-mode 3C509B). >=286-gated by caller.
%include "isapnp.asm"
%endif

%ifdef CFG_PCI
%include "pci_io.asm"
%include "pcibus.asm"
%endif

; install -- hook INT 60h + NIC IRQ, enable card int, free environment, DOS TSR-keep.
%include "install.asm"

;------------------------------------------------------------------------------
; build_plan -- resolve the per-generation hardware parameters and hand the composer its
; immediates. Two generation-dependent values: the Window-1 register base (3C509 at io_base,
; Corkscrew at io_base+0x10) and the SET_TX_START command (3C509 early-start vs 3C515
; store-and-forward). The PIO datapath FIFO immediate is the Window-1 base.
;------------------------------------------------------------------------------
build_plan:
        mov     ax, EL3_W1_DELTA_3C509                       ; default: 3C509/B layout
        cmp     byte [g_nic_gen], 0
        je      .gen_done
        mov     ax, EL3_W1_DELTA_VORTEX                      ; 3C515: registers relocated +0x10
.gen_done:
        add     ax, [g_nic_io]
        mov     [g_w1_base], ax             ; Window-1 data-register base (FIFO/status/free)
        ; PIO TX uses early-start on BOTH generations: the wire overlaps the FIFO fill, keeping a
        ; slow CPU near wire rate at 10 Mbit. The 3C515's former store-and-forward threshold (1536)
        ; exceeds a standard frame, so the wire never early-started -- serialized fill+transmit,
        ; ~16x slower at 286/10M (598 vs 9717 kbit/s). 100 Mbit uses DMA (PIO@100 is impractical),
        ; so SF bought nothing here; and DMA TX bypasses this FIFO threshold entirely.
        mov     bx, EL3_CMD_SET_TX_START | EL3_TX_START_THRESH
        mov     [g_tx_start], bx            ; precomputed SET_TX_START command
        mov     [g_plan_rx_imm], ax         ; PIO datapath FIFO immediate = Window-1 base
        mov     [g_plan_tx_imm], ax
        ; --- per-generation bus-master list-pointer register offsets (hardware-true, D3.1):
        ;     the ISA 3C515 aliases the master block at base+0x400; the PCI 90x parts put it
        ;     at BAR0+0x20. Resident words so the datapath is generation-blind. ---
        mov     word [g_dnlist_off], EL3_DN_LIST_ISA
        mov     word [g_uplist_off], EL3_UP_LIST_ISA
        cmp     byte [g_nic_gen], NIC_GEN_BOOMERANG
        jb      .lp_done
        mov     word [g_dnlist_off], EL3_DN_LIST_PCI
        mov     word [g_uplist_off], EL3_UP_LIST_PCI
.lp_done:
        ; --- resolve bus-master TX DMA: /d AND (3C515 or Boomerang/Cyclone) AND >=286.
        ;     3C509 has no engine; Vortex's is the Wn7 single-shot we don't drive (PIO). ---
        mov     byte [g_use_dma], 0
        cmp     byte [g_want_dma], 0
        je      .dma_resolved
        cmp     byte [g_nic_gen], NIC_GEN_CORKSCREW
        je      .dma_gen_ok
        cmp     byte [g_nic_gen], NIC_GEN_BOOMERANG
        jb      .dma_resolved                   ; Tomahawk / Vortex: PIO floor
.dma_gen_ok:
        cmp     byte [g_cpu_class], CPU_80286   ; >=286: real mode, phys = seg*16+off, 24-bit ISA-safe
        jb      .dma_resolved
        mov     byte [g_use_dma], 1
.dma_resolved:
        ; --- HW checksum capability: Cyclone (3C905B/C) with DMA active. The MODE stays off
        ;     until the stack opts in via XMS_DMA_CSUM_CTL (it must stop computing checksums). ---
        mov     byte [g_csum_ok], 0
        mov     byte [g_csum_mode], 0
        cmp     byte [g_nic_gen], NIC_GEN_CYCLONE
        jne     .csum_resolved
        cmp     byte [g_use_dma], 0
        je      .csum_resolved                  ; insertion rides the DPD path; PIO TX has no FSH
        mov     byte [g_csum_ok], 1
.csum_resolved:
        ; resident TX DMA path: 486+ uses the non-blocking ring (movsd slot copy, hidden by the
        ; faster core); 286 AND 386 use the blocking zero-copy single-transfer. (Phase 8b tier:
        ; ring threshold raised 386 -> 486. A 386's slower core can't usefully overlap the ring's
        ; per-frame movsd copy in a flood, and single-transfer is simpler + zero-copy; the ring's
        ; ~+47% at 100 Mbit -- 28668 vs 19570 kbit/s -- was measured on a fast (486+) core.)
        mov     byte [g_tx_ring], 0
        cmp     byte [g_cpu_class], CPU_80486
        jb      .ring_resolved
        mov     byte [g_tx_ring], 1
.ring_resolved:
        ; --- resolve FDDI-sized large frames: /j AND 3C515 (else standard Ethernet). Sets the RX
        ;     length mask to the 13-bit Corkscrew field so a >2047 B frame's length isn't truncated.
        ;     el3_init sets allowLargePackets in MacControl when g_use_large. ---
        mov     byte [g_use_large], 0
        mov     word [g_rx_len_mask], 0x07FF     ; default: standard Ethernet (11-bit-safe)
        cmp     byte [g_want_large], 0
        je      .large_resolved
        cmp     byte [g_nic_gen], 1              ; Corkscrew (3C515) only
        jne     .large_resolved
        mov     byte [g_use_large], 1
        mov     word [g_rx_len_mask], 0x1FFF     ; 13-bit length field (FDDI-sized RX)
.large_resolved:
        ret

;------------------------------------------------------------------------------
; compose_resident -- select + stitch + patch the planned fragments into resident_image.
; Records each fragment's landing offset in g_off[]. 8088-clean (movsb/stosw/loops).
; out: AX = emitted length (0 on missing fragment / over budget).
;------------------------------------------------------------------------------
compose_resident:
        ; g_off[] = 0xFFFF
        mov     di, g_off
        mov     cx, FRAG__COUNT
        mov     ax, 0xFFFF
        rep     stosw                   ; ES:DI (= DGROUP)

        mov     word [g_pos], 0
        mov     word [g_planptr], g_plan
        mov     word [g_step], G_PLAN_N
.step:
        mov     si, [g_planptr]
        mov     al, [si]                ; frag id
        mov     [g_curid], al
        inc     si
        mov     ax, [si]                ; imm0
        mov     [g_imm0], ax
        add     si, 2
        mov     [g_planptr], si

        mov     al, [g_curid]
        call    frag_lookup             ; -> DI = entry, CF=1 if none
        jc      .fail

        ; g_off[id] = pos
        mov     bl, [g_curid]
        xor     bh, bh
        shl     bx, 1
        mov     ax, [g_pos]
        mov     [g_off + bx], ax

        ; copy fragment bytes: resident_image[pos..] = entry.bytes[0..len)
        mov     cx, [di + 4]            ; len
        ; budget guard: pos + len must fit resident_image, else the rep movsb overruns into the
        ; stats / resident state that follow it. Fail the compose (AX=0 -> install aborts) instead.
        mov     ax, [g_pos]
        add     ax, cx
        cmp     ax, RESIDENT_IMAGE_MAX
        ja      .fail
        mov     si, [di + 6]            ; src ptr
        push    di
        mov     di, resident_image
        add     di, [g_pos]
        rep     movsb                   ; DS:SI -> ES:DI
        pop     di

        ; apply immediate patches (floor: all PATCH_IMM16 = io_base)
        xor     ch, ch
        mov     cl, [di + 2]            ; n_patches
        jcxz    .nopatch
        mov     si, [di + 8]            ; patch table ptr
.patch:
        mov     bx, [si]                ; patch.offset (within fragment)
        add     bx, [g_pos]
        mov     ax, [g_imm0]
        mov     [resident_image + bx], ax
        add     si, PATCH_ENTRY_SIZE
        loop    .patch
.nopatch:
        mov     ax, [di + 4]            ; pos += len
        add     [g_pos], ax

        dec     word [g_step]
        jnz     .step

        mov     ax, [g_pos]
        ret
.fail:
        xor     ax, ax
        ret

;------------------------------------------------------------------------------
; frag_lookup -- find the best fragment for (id=AL, class=g_cpu_class): matching id with
; the highest cpu_min that is <= the detected class. out: DI = entry, CF=0; CF=1 if none.
; clobbers BX, CX, DX (and DI).
;------------------------------------------------------------------------------
frag_lookup:
        mov     di, g_frags
        mov     cx, FRAG_TABLE_N
        xor     bx, bx                  ; bx = best entry (0 = none yet)
        xor     dl, dl                  ; dl = best cpu_min
.fl_loop:
        cmp     [di], al                ; entry.id == id?
        jne     .fl_next
        mov     dh, [di + 1]            ; entry.cpu_min
        cmp     dh, [g_cpu_class]
        ja      .fl_next                ; cpu_min > class -> not emittable
        or      bx, bx
        jz      .fl_take                ; first match
        cmp     dh, dl
        jbe     .fl_next                ; not a higher cpu_min than current best
.fl_take:
        mov     bx, di
        mov     dl, dh
.fl_next:
        add     di, FRAG_ENTRY_SIZE
        loop    .fl_loop

        or      bx, bx
        jz      .fl_none
        mov     di, bx
        clc
        ret
.fl_none:
        stc
        ret

;------------------------------------------------------------------------------
; copy_down -- floor: the image was composed in place in resident_image (no relocs in the
; PIO floor fragments), so this just reports the size in paragraphs. Real packing + reloc
; fixups arrive with cross-fragment references. in: AX = emitted len; out: AX = paragraphs.
;------------------------------------------------------------------------------
copy_down:
        add     ax, 15
        mov     cl, 4
        shr     ax, cl                  ; ceil(len / 16)
        ret

;------------------------------------------------------------------------------
; Diagnostic print helpers (COLD; DOS INT 21h). Clobber AX/CX/DX freely.
;------------------------------------------------------------------------------
print_str:                              ; DS:DX -> '$'-terminated string
        mov     ah, 9
        int     0x21
        ret
print_char:                             ; AL = character
        mov     dl, al
        mov     ah, 2
        int     0x21
        ret
print_hex16:                            ; AX = value -> 4 hex digits
        push    ax
        mov     al, ah
        call    print_hex8
        pop     ax
        call    print_hex8
        ret
print_hex8:                             ; AL = byte -> 2 hex digits
        push    ax
        mov     cl, 4
        shr     al, cl                  ; high nibble
        call    print_nib
        pop     ax                      ; low nibble (print_nib masks)
        call    print_nib
        ret
print_nib:                              ; AL low nibble -> hex char
        and     al, 0x0F
        add     al, '0'
        cmp     al, '9'
        jbe     .e
        add     al, 7                   ; 'A'..'F'
.e:
        mov     dl, al
        mov     ah, 2
        int     0x21
        ret
print_mac:                              ; " MAC=" + g_mac[0..5] as hex
        mov     dx, msg_mac
        call    print_str
        mov     si, g_mac
        mov     cx, 6
.pm:
        push    cx
        lodsb
        call    print_hex8
        pop     cx
        loop    .pm
        ret

;------------------------------------------------------------------------------
; parse_hex16 / parse_dec16 -- read a number from the command tail (ES:SI), stopping at the
; first non-digit. out: BX = value, SI advanced past the digits. Clobbers AX, CX (and DX/dec).
;------------------------------------------------------------------------------
parse_hex16:
        xor     bx, bx
.ph:    mov     al, [es:si]
        cmp     al, '0'
        jb      .ph_done
        cmp     al, '9'
        jbe     .ph_d09
        or      al, 0x20                ; tolower
        cmp     al, 'a'
        jb      .ph_done
        cmp     al, 'f'
        ja      .ph_done
        sub     al, 'a' - 10            ; 'a'..'f' -> 10..15
        jmp     .ph_acc
.ph_d09:
        sub     al, '0'                 ; '0'..'9' -> 0..9
.ph_acc:
        mov     cl, 4
        shl     bx, cl                  ; bx *= 16
        xor     ah, ah
        add     bx, ax
        inc     si
        jmp     .ph
.ph_done:
        ret

parse_dec16:
        xor     bx, bx
.pd:    mov     al, [es:si]
        cmp     al, '0'
        jb      .pd_done
        cmp     al, '9'
        ja      .pd_done
        sub     al, '0'
        mov     cx, bx                  ; bx = bx*10 + digit  (10x = ((4x)+x)*2)
        shl     bx, 1
        shl     bx, 1
        add     bx, cx
        shl     bx, 1
        xor     ah, ah
        add     bx, ax
        inc     si
        jmp     .pd
.pd_done:
        ret
